   "orig": "让这一切得以发生的关键数学性质，是 19 世纪末一位极富原创性的电气工程师兼数学物理学家奥利弗·亥维赛（Oliver Heaviside，1850–1925；我们在 6.1 节见过）就已注意到的一个表面上的「怪现象」。亥维赛发现，微分算符常常可以像普通数一样摆弄，这在解某几类微分方程时往往很好用。看一个例子。考虑微分方程 y + d²y/dx² = x⁵（符号含义见 6.3 节）。我们要找一个满足此式的具体函数 y = y(x)。亥维赛的办法是把 d/dx 当成普通数。为了让它显得更「说得过去」，用单个字母 D 记这个算符：D = d/dx。于是「D²」代表的是重复求导 d²/dx² = (d/dx)²，即二阶导数算符；「D³」代表三阶导数 d³/dx³，依此类推。方程就成了 y + D²y = x⁵，可写成 (1 + D²)y = x⁵。我们形式上「用 1 + D² 除过去」，把答案写成 y = (1 + D²)⁻¹x⁵。再把 (1 + D²)⁻¹ 按「D 的幂级数」展开，得 y = (1 − D² + D⁴ − D⁶ + …)x⁵。（4.3 节已讨论过这个级数，只是那里的 x 换成了 D。）注意（6.5 节）Dx⁵ = 5x⁴，D²x⁵ = 20x³，D³x⁵ = 60x²，D⁴x⁵ = 120x，D⁵x⁵ = 120，D⁶x⁵ = 0，等等，于是得到（正确的！）特解 y = x⁵ − 20x³ + 120x。只要把规则照应周全，这套形式做法完全可以严格化——不过亥维赛最初用它时，反对声可是铺天盖地。",
